.project-card {
  background-color: var(--color-surface-dark);
  border: 2px solid transparent;
  padding: var(--space-md);
  display: flex;
  flex-direction: column;
  gap: var(--space-sm);
  position: relative;
  /* Hover transitions fire immediately (≤200ms); stagger delay applies only to entrance animation */
  transition:
    box-shadow    var(--duration-fast) var(--ease-out),
    border-color  var(--duration-fast) var(--ease-out),
    opacity       var(--duration-enter) var(--ease-out) var(--stagger, 0ms),
    transform     var(--duration-enter) var(--ease-out) var(--stagger, 0ms);
}
